import{_ as e,o,c as i,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"La Era de Exploración Transplanar","description":"","frontmatter":{},"headers":[],"relativePath":"es/78-跨位面探索纪元.md","filePath":"es/78-跨位面探索纪元.md"}'),s={name:"es/78-跨位面探索纪元.md"};function r(l,a,t,d,c,p){return o(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="la-era-de-exploracion-transplanar" tabindex="-1">La Era de Exploración Transplanar <a class="header-anchor" href="#la-era-de-exploracion-transplanar" aria-label="Permalink to &quot;La Era de Exploración Transplanar&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>78</td></tr><tr><td>Módulo</td><td>Eras Históricas y Grandes Acontecimientos</td></tr><tr><td>Palabras clave</td><td>exploración transplanar, grandes descubrimientos de planos, protocolo arqueológico, observar primero luego interferir, simbiosis interestelar</td></tr></tbody></table><h2 id="i-las-condiciones-de-apertura-de-la-era-de-exploracion-transplanar" tabindex="-1">I. Las Condiciones de Apertura de la Era de Exploración Transplanar <a class="header-anchor" href="#i-las-condiciones-de-apertura-de-la-era-de-exploracion-transplanar" aria-label="Permalink to &quot;I. Las Condiciones de Apertura de la Era de Exploración Transplanar&quot;">​</a></h2><p>La Era de Exploración Transplanar es una nueva era abierta tras la fundación de la República de las Diez Mil Razas, correspondiente a la etapa de transición de la &quot;evolución de la conciencia&quot; a la &quot;simbiosis interestelar&quot; en el camino de ascensión en cuatro etapas. La apertura de esta era exigía la maduración simultánea de tres condiciones:</p><ul><li><strong>Condición tecnológica</strong>: la tecnología de principios legales espaciales alcanzó el reino del &quot;Vacío de Origen&quot;, haciendo posible la apertura estable de pasajes transplanares; el Espejo de Réplica y las tecnologías de espacio aislado maduraron, proporcionando garantías técnicas para la exploración de baja contaminación.</li><li><strong>Condición institucional</strong>: se fundó la República de las Diez Mil Razas, y se completaron las políticas unificadas de exploración transplanar y el protocolo arqueológico.</li><li><strong>Condición de motivación</strong>: el trabajo de ascensión de los planos conocidos avanzó de manera ordenada, y la civilización tenía tanto la capacidad como la voluntad de expandirse hacia planos desconocidos.</li></ul><p>Cuando estas tres condiciones maduraron simultáneamente, la República de las Diez Mil Razas anunció oficialmente el lanzamiento del &quot;Gran Plan de Exploración&quot;, y la Era de Exploración Transplanar comenzó así.</p><h2 id="ii-los-principios-basicos-de-la-exploracion-transplanar" tabindex="-1">II. Los Principios Básicos de la Exploración Transplanar <a class="header-anchor" href="#ii-los-principios-basicos-de-la-exploracion-transplanar" aria-label="Permalink to &quot;II. Los Principios Básicos de la Exploración Transplanar&quot;">​</a></h2><p>La exploración transplanar sigue estrictamente los siguientes principios básicos, inscritos en la &quot;Ley Fundamental de Exploración Transplanar&quot;:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Observar primero, luego interferir de forma limitada</td><td>Los planos desconocidos se someten primero a observación pasiva; solo tras una comprensión completa se realizan contactos e interferencias limitadas</td></tr><tr><td>Exploración de baja contaminación</td><td>Adopta el esquema arqueológico de Espejo de Réplica + espacio aislado, transmitiendo solo conocimiento, sin llevar materia o vida adentro o afuera</td></tr><tr><td>Protección de las civilizaciones autóctonas</td><td>Para los planos con civilizaciones autóctonas, respetar su derecho al desarrollo autónomo; no imponer por la fuerza el sistema simbiótico</td></tr><tr><td>Intercambio de recursos</td><td>El conocimiento y los recursos descubiertos por la exploración pertenecen a toda la civilización; ninguna organización puede monopolizar los resultados de la exploración</td></tr><tr><td>Seguridad primero</td><td>La seguridad siempre tiene prioridad durante la exploración; la exploración de planos de alto riesgo debe pasar por una estricta evaluación de riesgos</td></tr></tbody></table><h2 id="iii-los-medios-tecnicos-de-la-exploracion" tabindex="-1">III. Los Medios Técnicos de la Exploración <a class="header-anchor" href="#iii-los-medios-tecnicos-de-la-exploracion" aria-label="Permalink to &quot;III. Los Medios Técnicos de la Exploración&quot;">​</a></h2><p>La exploración transplanar empleó de manera integral múltiples tecnologías centrales de la civilización simbiótica:</p><ol><li><strong>Tecnología de escaneo de planos</strong>: el escaneo remoto de planos, basado en módulos de percepción de principios legales espaciales, puede obtener información básica de un plano objetivo sin contactarlo (estructura espacial, nivel de energía, signos de vida, etc.).</li><li><strong>Esquema arqueológico del Espejo de Réplica</strong>: realiza una réplica especular de alta precisión del plano objetivo, llevando a cabo una investigación profunda sobre la copia especular en espacio aislado, transmitiendo solo conocimiento.</li><li><strong>Sondas de comunicación transplanar</strong>: dispositivos diminutos de comunicación por leyes que pueden enviarse al plano objetivo para observación cercana, con datos transmitidos en tiempo real a través de la red de comunicación transplanar.</li><li><strong>Percepción del dominio de la conciencia</strong>: los cultivadores de alto nivel perciben remotamente el plano objetivo a través del dominio de la conciencia, obteniendo información a nivel de conciencia que la tecnología de escaneo no puede captar.</li><li><strong>Despliegue remoto del Ancla</strong>: para planos con un nivel de seguridad más alto, pueden desplegarse remotamente Anclas temporales para establecer canales de conexión estables.</li></ol><h2 id="iv-la-organizacion-e-implementacion-de-la-exploracion" tabindex="-1">IV. La Organización e Implementación de la Exploración <a class="header-anchor" href="#iv-la-organizacion-e-implementacion-de-la-exploracion" aria-label="Permalink to &quot;IV. La Organización e Implementación de la Exploración&quot;">​</a></h2><p>La exploración transplanar es organizada e implementada de manera unificada por la &quot;Oficina de Exploración Transplanar&quot; de la República de las Diez Mil Razas, adoptando un modelo de &quot;exploración graduada&quot;:</p><table tabindex="0"><thead><tr><th>Nivel de exploración</th><th>Tipo de objetivo</th><th>Método de exploración</th><th>Configuración de personal</th></tr></thead><tbody><tr><td>Exploración de Primer Nivel</td><td>Planos yermos sin vida</td><td>Escaneo remoto + investigación con Espejo de Réplica</td><td>Equipos técnicos principalmente</td></tr><tr><td>Exploración de Segundo Nivel</td><td>Planos con vida de bajo nivel</td><td>Arqueología con Espejo de Réplica + investigación de campo limitada</td><td>Equipos técnicos + biólogos</td></tr><tr><td>Exploración de Tercer Nivel</td><td>Planos con civilizaciones autóctonas</td><td>Observar primero, luego contactar, siguiendo estrictamente el protocolo de contacto</td><td>Equipo completo + diplomáticos + observadores éticos</td></tr><tr><td>Exploración de Cuarto Nivel</td><td>Planos de alto riesgo/desconocidos</td><td>Solo investigación simulada en espacio aislado, contacto de campo prohibido</td><td>Equipo de seguridad del más alto nivel</td></tr></tbody></table><p>Cada proyecto de exploración debe pasar por el proceso completo de &quot;solicitud de exploración — evaluación de riesgos — revisión ética — aprobación e implementación — monitoreo del proceso — intercambio de resultados&quot;.</p><h2 id="v-los-grandes-descubrimientos-de-la-era-de-exploracion" tabindex="-1">V. Los Grandes Descubrimientos de la Era de Exploración <a class="header-anchor" href="#v-los-grandes-descubrimientos-de-la-era-de-exploracion" aria-label="Permalink to &quot;V. Los Grandes Descubrimientos de la Era de Exploración&quot;">​</a></h2><p>Tras la apertura de la Era de Exploración Transplanar, la civilización simbiótica logró una serie de grandes descubrimientos:</p><ul><li><strong>Descubrimiento de nuevas razas</strong>: se descubrieron en planos desconocidos un gran número de razas inteligentes antes desconocidas, ampliando enormemente la genealogía de las Diez Mil Razas. Estas nuevas razas se unieron gradualmente a la República de las Diez Mil Razas tras elección voluntaria.</li><li><strong>Descubrimiento de nuevas leyes</strong>: las estructuras de leyes de los distintos planos difieren, y se descubrieron durante la exploración numerosas variantes nuevas de leyes, enriqueciendo los fundamentos teóricos de los Trescientos Sistemas de Cultivo.</li><li><strong>Ruinas de civilizaciones antiguas</strong>: se descubrieron las ruinas de varias civilizaciones extinguidas de la Era Pre-Ancla, obteniéndose una gran cantidad de valiosos conocimientos históricos mediante la arqueología del Espejo de Réplica.</li><li><strong>Civilizaciones simbióticas de otros planos</strong>: en ciertos planos se descubrieron civilizaciones autóctonas que desarrollaron de manera independiente el concepto de simbiosis, formando con la Civilización Simbiótica del Ancla una resonancia de pensamiento a través del espacio.</li><li><strong>Exploración de la frontera del universo</strong>: la exploración tocó gradualmente la frontera conocida del Universo Hengyuan, profundizando continuamente la comprensión de la estructura general del universo.</li></ul><h2 id="vi-desafios-y-reflexiones-en-la-exploracion" tabindex="-1">VI. Desafíos y Reflexiones en la Exploración <a class="header-anchor" href="#vi-desafios-y-reflexiones-en-la-exploracion" aria-label="Permalink to &quot;VI. Desafíos y Reflexiones en la Exploración&quot;">​</a></h2><p>La exploración transplanar no fue un camino de rosas; el proceso también encontró desafíos:</p><ul><li><strong>Conflictos culturales</strong>: surgieron malentendidos y conflictos culturales en el contacto con las civilizaciones autóctonas, impulsando la mejora continua del protocolo de contacto.</li><li><strong>Controversias éticas de la exploración</strong>: hubo debates éticos continuos sobre &quot;si se debe contactar activamente a las civilizaciones autóctonas&quot;, formándose finalmente el consenso de &quot;no proactivo, no evasivo, respeto de las elecciones&quot;.</li><li><strong>Incidentes de seguridad</strong>: se produjo una ruptura de la barrera de espacio aislado durante la exploración de un plano de alto riesgo; aunque no causó consecuencias graves, impulsó una mayor elevación de los estándares de seguridad.</li><li><strong>Asignación de recursos</strong>: la exploración a gran escala consume recursos considerables, y el equilibrio entre la inversión en exploración y la inversión en el bienestar local se convirtió en el centro del debate político.</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La Era de Exploración Transplanar es la &quot;era de los grandes descubrimientos marítimos&quot; de la Civilización Simbiótica del Ancla. Extendió los horizontes de la civilización de los planos conocidos a todo el universo, profundizando la comprensión de sí misma mientras descubría nuevos mundos. El esquema de exploración de baja contaminación de Espejo de Réplica + espacio aislado hace que la exploración de la civilización simbiótica sea fundamentalmente distinta de toda expansión colonial depredadora de la historia — lo que llevamos no es conquista y depredación, sino respeto y conocimiento; lo que traemos de vuelta no son recursos y esclavos, sino comprensión y sabiduría. Cuando se hayan explorado suficientes planos y la red del Ancla sea lo bastante densa, la puerta de la Era de la Simbiosis Interestelar se abrirá lentamente.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>77-万族共和成立 (La Fundación de la República de las Diez Mil Razas)</li><li>79-星际共生时代展望 (Las Perspectivas de la Era de la Simbiosis Interestelar)</li><li>84-考古协议总纲 (El Esquema General del Protocolo Arqueológico)</li></ul>',26)])])}const b=e(s,[["render",r]]);export{m as __pageData,b as default};
